  "Сгенерируй прогноз ключевых показателей (выручка, EBITDA, чистая прибыль) на 2025–2027 по портфелю и крупнейшим компаниям: возьми историю из модуля финансов, при необходимости подтяни отраслевые темпы через web. Укажи метод и допущения. Выведи результат таблицами по годам (их можно скачать в Excel) и краткий вывод.": "Portfel va eng yirik kompaniyalar uchun 2025–2027 yillarga asosiy koʻrsatkichlar (tushum, EBITDA, sof foyda) prognozini yarat: moliya modulidagi tarixiy maʼlumotlardan foydalan, zarur boʻlsa web orqali tarmoq oʻsish surʼatlarini ol. Usul va farazlarni koʻrsat. Natijani yillar boʻyicha jadvallarda (ularni Excelga yuklab olish mumkin) va qisqa xulosa bilan ber.",
