  "ИИ-аналитик": "AI tahlilchi",
  "портфель · все компании": "portfel · barcha kompaniyalar",
  "Доступ к web-поиску. Таблицы из ответа можно скачать в Excel (кнопка под ответом). ИИ может ошибаться — проверяйте важные цифры.": "Web qidiruviga kirish mavjud. Javobdagi jadvallarni Excelga yuklab olish mumkin (javob ostidagi tugma). AI xato qilishi mumkin — muhim raqamlarni tekshiring.",
  "Прогноз ИИ — выручка · EBITDA · прибыль на 2025–2027": "AI prognozi — 2025–2027 yillarga tushum · EBITDA · foyda",
