  "Расчётная оценка: 12% × выручка (НСБУ). Не учитывает нулевую ставку НДС на экспорт и зачёт входящего НДС — фактический НДС к уплате ниже. Для факта заполните «Налоги» в индикаторах компаний.": "Hisobiy baho: 12% × tushum (BHMS). Eksport uchun QQSning nol stavkasi va kiruvchi QQS hisobga olinmagan — amalda toʻlanadigan QQS kamroq. Fakt uchun kompaniya indikatorlaridagi «Soliqlar»ni toʻldiring.",
