  "Удалить override для этого кредита?": "Ushbu kredit uchun override o‘chirilsinmi?",
  "Раздел для управления сценариями кредитной нагрузки 22 SOEs. Все правки изолированы — не влияют на factual данные в credit-portfolio.": "22 ta SOE kredit yuklamasi ssenariylarini boshqarish bo‘limi. Barcha o‘zgarishlar alohida saqlanadi va credit-portfolio dagi fakt maʼlumotlariga taʼsir qilmaydi.",
  "Выбранный сценарий применяется ко всем расчётам ниже (KPI, формула риска, прогноз погашения).": "Tanlangan ssenariy quyidagi barcha hisob-kitoblarga (KPI, xavf formulasi, to‘lov prognozi) qo‘llanadi.",
  "Выбор подмножества кредиторов для всех KPI и графиков ниже. По умолчанию — внутренние РУ (гос. + местные).": "Quyidagi barcha KPI va grafiklar uchun kreditorlar to‘plamini tanlang. Standart holatda ichki kreditorlar (davlat + mahalliy) olinadi.",
  "Сводка по портфелю в области охвата. Пересчитывается при смене сценария.": "Qamrovdagi portfel bo‘yicha yig‘ma maʼlumot. Ssenariy o‘zgarganda qayta hisoblanadi.",
  "Текущая задолженность по выбранному scope. Учитывает % списания из сценария.": "Tanlangan qamrov bo‘yicha joriy qarzdorlik. Ssenariydagi hisobdan chiqarish foizini inobatga oladi.",
  "Возвращено = Программа − Outstanding. Включает плановые и досрочные выплаты.": "Qaytarilgan = Dastur − Outstanding. Rejali va muddatidan oldingi to‘lovlarni o‘z ichiga oladi.",
  "Σ(rate × debt) / Σ debt — взвешенная по размеру долга. Учитывает изменение ставки рефинанса из сценария.": "Σ(rate × debt) / Σ debt — qarz miqdori bo‘yicha vaznlangan. Ssenariydagi qayta moliyalash stavkasi o‘zgarishini hisobga oladi.",
  "Доля кредитов с госгарантией. Влияет на recovery rate в формуле EL.": "Davlat kafolatiga ega kreditlar ulushi. EL formulasidagi recovery rate ga taʼsir qiladi.",
  "Платежи следующих 12 месяцев — основной долг + проценты по графику.": "Keyingi 12 oydagi to‘lovlar — jadval bo‘yicha asosiy qarz + foizlar.",
  "Expected Loss = Σ debt × PD × (1 − RR). PD из формулы, RR из risk_rr_by_lender или is_guaranteed.": "Expected Loss = Σ debt × PD × (1 − RR). PD formuladan, RR risk_rr_by_lender yoki is_guaranteed dan olinadi.",
  "Базовые гипотезы — применяются ко всему портфелю в этом сценарии. Сохраняются автоматически.": "Asosiy taxminlar ushbu ssenariydagi butun portfelga qo‘llanadi. Avtomatik saqlanadi.",
  "% основного долга, который государство простит. Применяется к кредитам с lender_type='state'.": "Davlat kechadigan asosiy qarz foizi. lender_type='state' bo‘lgan kreditlarga qo‘llanadi.",
  "Изменение ставки рефинансирования в процентных пунктах (+/-). Применяется к гос. + местным.": "Qayta moliyalash stavkasining foiz punktlaridagi o‘zgarishi (+/-). Davlat + mahalliy kreditlarga qo‘llanadi.",
  "Базовая вероятность дефолта в этом сценарии (PD baseline). Может быть переопределена per-loan.": "Ushbu ssenariydagi asosiy defolt ehtimoli (PD baseline). Har bir kredit bo‘yicha alohida override qilish mumkin.",
  "% ускорения выплат от планового графика. Используется в прогнозе погашения.": "Rejali jadvalga nisbatan to‘lovlarni tezlashtirish foizi. To‘lov prognozida ishlatiladi.",
  "Python-выражение для расчёта Expected Loss. Возвращает финальное значение EL в USD. Безопасный AST-eval (без simpleeval).": "Expected Loss hisoblash uchun Python ifodasi. Yakuniy EL qiymatini USD da qaytaradi. Xavfsiz AST-eval (simpleeval siz).",
  "Custom-переменные, доступные в формуле через custom.<key>. Например: 'доля юаня', 'мораторий 2026'.": "Formulada custom.<key> orqali mavjud maxsus o‘zgaruvchilar. Masalan: 'yuanning ulushi', 'moratoriy 2026'.",
  "Топ-N кредитов по размеру долга. Inline-редактирование override: forgiveness% (% списания) и rate_override (новая ставка).": "Qarz miqdori bo‘yicha top-N kredit. Har bir kredit override ini inline tahrirlash: forgiveness% (hisobdan chiqarish %) va rate_override (yangi stavka).",
  "Read-only визуализация: топ-должники по Debt/EBITDA и квартальный график погашения.": "Faqat ko‘rish uchun: Debt/EBITDA bo‘yicha eng yirik qarzdorlar va choraklik to‘lov jadvali.",
  "Debt/EBITDA = долг / прибыль до налогов и амортизации. <2.5 здоровый, 2.5–3 повышенный, >3 критический.": "Debt/EBITDA = qarz / soliq va amortizatsiyagacha bo‘lgan foyda. <2.5 sog‘lom, 2.5–3 yuqori, >3 kritik.",
  "Сумма плановых выплат (основной долг + проценты) по годам 2023–2030. Источник: loan_repayments.": "2023–2030-yillar bo‘yicha rejali to‘lovlar summasi (asosiy qarz + foizlar). Manba: loan_repayments.",
