  "{value0} млрд сум": "{value0} mlrd so‘m",
  "{value0} млн сум": "{value0} mln so‘m",
  "Раздел связывает макроэкономику со сценариями. Состоит из 3 частей: эластичность (как метрики реагируют на макрофакторы), эффекты проектов (что даёт каждый проект в цифрах), декомпозиция (из чего складывается прогноз).": "Bo‘lim makroiqtisodiyotni ssenariylar bilan bog‘laydi. U 3 qismdan iborat: elastiklik (ko‘rsatkichlar makroomillarga qanday javob beradi), loyiha effektlari (har bir loyihaning raqamlardagi natijasi) va dekompozitsiya (prognoz nimalardan tuziladi).",
  "Эластичность β — на сколько % изменится метрика (например revenue) при изменении макрофактора (например USD-курс) на 1%. Если β=0.85 — это значит USD вырос на 10% → revenue вырастет на 8.5%.": "Elastiklik β — makroomil (masalan, USD kursi) 1% ga o‘zgarganda ko‘rsatkich (masalan, revenue) necha foizga o‘zgarishi. β=0.85 bo‘lsa, USD 10% ga oshganda revenue 8.5% ga oshadi.",
  "Финансовые эффекты конкретных проектов трансформации. Команда проекта указывает: проект «X» в 2027 году даст +120 млрд сум к выручке с вероятностью 75%. Программа потом суммирует все такие эффекты в декомпозиции.": "Muayyan transformatsiya loyihalarining moliyaviy effektlari. Loyiha jamoasi, masalan, «X» loyihasi 2027-yilda 75% ehtimol bilan tushumga +120 mlrd so‘m qo‘shishini ko‘rsatadi. Dastur keyin barcha effektlarni dekompozitsiyada jamlaydi.",
  "Раскладывает прогноз на 3 части: База (факт прошлого года) + Эффект макроэкономики (через эластичности) + Эффект проектов (из их финансовых данных). Помогает понять, что именно даёт рост.": "Prognozni 3 qismga ajratadi: Baza (o‘tgan yil fakti) + Makroiqtisodiy effekt (elastikliklar orqali) + Loyiha effekti (moliyaviy maʼlumotlaridan). O‘sish manbasini tushunishga yordam beradi.",
  "Иерархия применения коэффициента: специфичный сценарий + компания > сценарий > компания > глобально. Программа берёт самый специфичный из имеющихся.": "Koeffitsiyentni qo‘llash ierarxiyasi: muayyan ssenariy + kompaniya > ssenariy > kompaniya > global. Dastur mavjudlaridan eng aniq ko‘rsatilganini oladi.",
  "Эластичность и эффекты проектов": "Elastiklik va loyiha effektlari",
  "Связывает макроэкономику со сценариями:": "Makroiqtisodiyotni ssenariylar bilan bog‘laydi:",
  "эластичность": "elastiklik",
  "= чувствительность к макрофакторам ·": "= makroomillarga sezgirlik ·",
  "эффекты проектов": "loyiha effektlari",
  "= эффект конкретных проектов в цифрах ·": "= muayyan loyihaning raqamlardagi effekti ·",
  "декомпозиция": "dekompozitsiya",
  "= из чего складывается прогноз.": "= prognoz nimalardan tuziladi.",
  "⟳ Обновить": "⟳ Yangilash",
  "Матрица эластичности": "Elastiklik matritsasi",
  "Эффекты проектов": "Loyiha effektlari",
  "Декомпозиция прогноза": "Prognoz dekompozitsiyasi",
  "Что это:": "Bu nima:",
  "Как читать β:": "β ni qanday o‘qish kerak:",
  "β &gt; 0 — растёт вместе с фактором": "β &gt; 0 — omil bilan birga o‘sadi",
