  "Влияет на": "Taʼsir qiladi",
  "Нет коэффициентов в этом срезе. Запустите миграции и сидинг через": "Bu kesimda koeffitsiyentlar yo‘q. Global standartlarni yaratish uchun migratsiyalar va seeding ni ishga tushiring:",
  "чтобы создать глобальные дефолты.": "global standartlarni yaratish uchun.",
  "Логика:": "Mantiq:",
  "у каждого проекта может быть много эффектов — один на каждую пару (год × метрика). Например: «Modernize plant X»: +50 млрд сум к revenue в 2026, +120 в 2027.": "har bir loyihada ko‘plab effektlar — har bir (yil × ko‘rsatkich) juftligi uchun bittadan bo‘lishi mumkin. Masalan: «Modernize plant X»: 2026-yilda revenue ga +50 mlrd so‘m, 2027-yilda +120 mlrd.",
  "Заполнение:": "To‘ldirish:",
  "данные вносят команды проектов. Пока поля пустые — прогноз считает что эффект = 0. Появятся данные → автоматически отразятся в декомпозиции.": "maʼlumotlarni loyiha jamoalari kiritadi. Maydonlar bo‘sh bo‘lsa, prognoz effektni 0 deb hisoblaydi. Maʼlumot paydo bo‘lganda u dekompozitsiyada avtomatik aks etadi.",
  "+ Добавить эффект": "+ Effekt qo‘shish",
