  "Выбери сценарий, метрику и год и нажми «Рассчитать». Если база = 0 — значит для этой компании нет финансовых данных за предыдущий год.": "Ssenariy, ko‘rsatkich va yilni tanlab, «Hisoblash»ni bosing. Baza = 0 bo‘lsa, bu kompaniya uchun oldingi yil moliyaviy maʼlumotlari yo‘q.",
