  "Среднее отклонение <b style=\"color:#C53030\">+{deviation}%</b> требует внимания. Особое отклонение в категории <b>{category}</b> ({worstDeviation}%). Рекомендуется аудит закупочных процедур и пересмотр поставщиков по топ-3 проблемным категориям. Потенциал экономии при переходе на средние цены — <b>{amount} сум/год</b>.": "O‘rtacha og‘ish <b style=\"color:#C53030\">+{deviation}%</b> eʼtibor talab qiladi. <b>{category}</b> toifasidagi og‘ish ayniqsa katta ({worstDeviation}%). Xarid tartiblarini audit qilish va muammoli top-3 toifa bo‘yicha yetkazib beruvchilarni qayta ko‘rib chiqish tavsiya etiladi. O‘rtacha narxlarga o‘tishdagi tejamkorlik salohiyati — <b>yiliga {amount} so‘m</b>.",
  "Среднее отклонение <b style=\"color:#B07415\">+{deviation}%</b> — в пределах нормы. По {redCount} категориям из {categoryCount} закупка выше рынка. Рекомендуется мониторинг этих категорий и сравнение поставщиков с лидерами рейтинга.": "O‘rtacha og‘ish <b style=\"color:#B07415\">+{deviation}%</b> — meʼyor doirasida. {categoryCount} ta toifadan {redCount} tasida xarid bozordan yuqori. Bu toifalarni kuzatish va yetkazib beruvchilarni reyting yetakchilari bilan taqqoslash tavsiya etiladi.",
  "Среднее отклонение <b style=\"color:#0F6E56\">{deviation}%</b> — закупки эффективнее рынка. Хорошие закупочные практики — стоит задокументировать методику и поделиться с другими компаниями. Экономия за период составила <b>{amount} сум</b>.": "O‘rtacha og‘ish <b style=\"color:#0F6E56\">{deviation}%</b> — xaridlar bozordan samaraliroq. Yaxshi xarid amaliyotini hujjatlashtirib, boshqa kompaniyalar bilan ulashish kerak. Davr davomida tejamkorlik <b>{amount} so‘m</b>ni tashkil etdi.",
  "не авторизован": "tizimga kirmagan",
