  "Удержание последнего факта без роста. Доп. данные не нужны.": "So‘nggi faktni o‘sishsiz saqlaydi. Qo‘shimcha maʼlumot kerak emas.",
  "ШАБЛОН ИМПОРТА · Закупки и Форензик аудит · {year} год": "IMPORT SHABLONI · Xaridlar va Forenzik audit · {year}-yil",
  "КАК ЗАПОЛНЯТЬ:": "TO‘LDIRISH TARTIBI:",
  "1. Лист «Компании» — справочник, не редактируйте.": "1. «Kompaniyalar» varag‘i — maʼlumotnoma, uni tahrirlamang.",
  "2. Лист «Данные» — заполните по каждой компании план/факт по году + квартально.": "2. «Maʼlumotlar» varag‘i — har bir kompaniya bo‘yicha yillik va choraklik reja/faktni to‘ldiring.",
  "ПОЛЯ:": "MAYDONLAR:",
  "• Код компании — обязателен, ровно как в листе «Компании».": "• Kompaniya kodi — kiritilishi shart va «Kompaniyalar» varag‘idagi bilan aynan bir xil bo‘lishi kerak.",
