  "• Все суммы — в млрд сум, только числа (без пробелов / валют).": "• Barcha summalar — mlrd so‘mda, faqat sonlar (bo‘shliq / valyutasiz).",
  "• Статус плана: «Утверждён» / «Не утверждён» / пусто.": "• Reja holati: «Tasdiqlangan» / «Tasdiqlanmagan» / bo‘sh.",
  "• Статус форензика: «Завершён» / «В процессе» / «Тендер в YYYY» / «Не начат» / пусто.": "• Forenzik holati: «Yakunlangan» / «Jarayonda» / «YYYY da tender» / «Boshlanmagan» / bo‘sh.",
