  "КАК ИМПОРТИРОВАТЬ": "IMPORT QILISH TARTIBI",
  "1. Один лист = одна компания. Имя листа — КОД из таблицы «Коды компаний» (NGMK, AGMK…). Регистр не важен.": "1. Bitta varaq = bitta kompaniya. Varaq nomi «Kompaniya kodlari» jadvalidagi KOD bo‘lishi kerak (NGMK, AGMK…). Registr muhim emas.",
  "2. Первая строка листа — заголовки колонок РОВНО как на листе «ОБРАЗЕЦ» (имена нельзя менять/переводить).": "2. Varaqning birinchi qatori — ustun sarlavhalari aynan «NAMUNA» varag‘idagi kabi (nomlarni o‘zgartirish/tarjima qilish mumkin emas).",
  "3. Каждая следующая строка — одна позиция (товар/услуга/работа) внутри лота.": "3. Har bir keyingi qator — lot ichidagi bitta pozitsiya (tovar/xizmat/ish).",
  "4. Несколько товаров одного лота — несколько строк с ОДНИМ lotId (сумма контракта учитывается один раз).": "4. Bitta lotdagi bir necha tovar — bir xil lotId bilan bir necha qator (shartnoma summasi bir marta hisoblanadi).",
  "5. Листы «СПРАВКА» и «ОБРАЗЕЦ» при импорте игнорируются (их имена — не коды компаний).": "5. «MAʼLUMOT» va «NAMUNA» varaqlari importda eʼtiborga olinmaydi (ularning nomlari kompaniya kodlari emas).",
  "6. Загрузка: модуль «Анализ закупок» → меню ⋯ → Импорт Excel.": "6. Yuklash: «Xaridlar tahlili» moduli → ⋯ menyu → Excel importi.",
  "КОЛОНКИ (имя — обязательность — описание)": "USTUNLAR (nomi — majburiyligi — tavsifi)",
  "обязательно": "majburiy",
  "ID лота/контракта. Строки с одним lotId = один лот.": "Lot/shartnoma ID. Bir xil lotId ga ega qatorlar = bitta lot.",
  "желательно": "tavsiya etiladi",
