  "Номер категории 1–15 (см. «Категории»). Пусто → «Без категории».": "1–15 toifa raqami («Toifalar»ga qarang). Bo‘sh → «Toifasiz».",
  "ВАЖНО": "MUHIM",
  "Код товара (KTRU). По нему считается рыночная медиана и сравнение цен. Без кода — позиция не попадёт в ценовой бенчмарк.": "Tovar kodi (KTRU). Bozor medianasi va narx taqqoslash shu kod bo‘yicha hisoblanadi. Kodsiz pozitsiya narx benchmarkiga kirmaydi.",
  "Наименование товара/услуги.": "Tovar/xizmat nomi.",
  "PRODUCT (товар) / SERVICE (услуга) / WORK (работа). Пусто → определяется по ед.изм.": "PRODUCT (tovar) / SERVICE (xizmat) / WORK (ish). Bo‘sh → o‘lchov birligi bo‘yicha aniqlanadi.",
  "Единица измерения (шт, кг, т, л … ; для услуг часто «shartli birlik»).": "O‘lchov birligi (dona, kg, t, l …; xizmatlar uchun ko‘pincha «shartli birlik»).",
  "Количество (число > 0).": "Miqdor (son > 0).",
  "обязательно*": "majburiy*",
  "Цена за единицу (число > 0). *Если пусто — будет вычислено как contractAmount / amount.": "Birlik narxi (son > 0). *Bo‘sh bo‘lsa, contractAmount / amount sifatida hisoblanadi.",
  "Начальная сумма процедуры (UZS).": "Tartibning boshlang‘ich summasi (UZS).",
  "Сумма контракта (UZS). Источник «спенда» лота; при пустой Unit price — основа для расчёта цены.": "Shartnoma summasi (UZS). Lot «xarajati» manbasi; Unit price bo‘sh bo‘lsa, narxni hisoblash asosi.",
