  "Это необратимо. Если хотите сохранить историю, отключите «Активен» вместо полного удаления.": "Buni qaytarib bo‘lmaydi. Tarixni saqlash uchun butunlay o‘chirish o‘rniga «Faol»ni o‘chiring.",
