  "Заполнить «Сводный обзор» вручную: направления, проекты по кварталам и детали в выноску": "«Yig‘ma sharh»ni qo‘lda to‘ldirish: yo‘nalishlar, choraklar bo‘yicha loyihalar va izoh blokidagi tafsilotlar",
  "Ключевые результаты бизнес-плана за Q1 (факт / план)": "Q1 biznes-rejaning asosiy natijalari (fakt / reja)",
