  "Ход": "Jarayon",
  "Год {year}; секторы: {sectors}": "{year}-yil; sektorlar: {sectors}",
  "Дай аналитическую сводку по портфелю из 22 SOE: ключевые цифры, лидеры и отстающие, общая динамика. Используй get_kpi_summary.": "22 ta SOE portfeli bo‘yicha tahliliy xulosa ber: asosiy raqamlar, yetakchilar va ortda qolganlar, umumiy dinamika. get_kpi_summary dan foydalan.",
  "Найди топ-3 риска в портфеле: где провал KPI, где просрочки концентрируются, где credit-risk. Конкретные компании + рекомендации.": "Portfeldagi top-3 xavfni top: KPI qayerda bajarilmagan, kechikishlar qayerda to‘plangan va kredit xavfi qayerda. Aniq kompaniyalar va tavsiyalarni ber.",
  "Проанализируй IPO-готовность портфеля: какие компании ближе всего к IPO, какие блокеры (governance/ESG/KPI) у каждой из IPO-roadmap.": "Portfelning IPO ga tayyorligini tahlil qil: qaysi kompaniyalar IPO ga eng yaqin va IPO roadmap dagi har bir kompaniya uchun qanday to‘siqlar bor (governance/ESG/KPI).",
  "Используй compare_years, чтобы сравнить выполнение задач 2025 vs 2026 и compare_companies по EBITDA. Сделай вывод.": "2025 va 2026-yillardagi vazifalar bajarilishini taqqoslash uchun compare_years, EBITDA bo‘yicha kompaniyalarni taqqoslash uchun compare_companies dan foydalan. Xulosa chiqar.",
  "Что важного на сегодня: просроченные критичные задачи, недавние события модерации, активные алерты. Используй list_overdue_tasks + get_moderation_queue + list_notifications.": "Bugungi muhim holatlar: kritik kechikkan vazifalar, so‘nggi moderatsiya hodisalari, faol ogohlantirishlar. list_overdue_tasks + get_moderation_queue + list_notifications dan foydalan.",
  "FY {year} · {standard} · {currency} · {unit} · {view} · метрика {metric}": "FY {year} · {standard} · {currency} · {unit} · {view} · ko‘rsatkich {metric}",
  " · сектор {sector}": " · sektor {sector}",
  "Дай сводку финансовых результатов портфеля за выбранный год: revenue, EBITDA, net profit, топ-5 компаний. Используй get_financials.": "Tanlangan yil uchun portfel moliyaviy natijalari xulosasini ber: revenue, EBITDA, net profit, top-5 kompaniya. get_financials dan foydalan.",
  "Проанализируй EBITDA-margin по портфелю: лидеры и отстающие, сравнение с отраслевыми бенчмарками (mining 25-45%, energy 15-25%, transport 10-20%, telecom 30-45%).": "Portfeldagi EBITDA margin ni tahlil qil: yetakchilar va ortda qolganlar, sektor benchmarklari bilan taqqoslash (mining 25-45%, energy 15-25%, transport 10-20%, telecom 30-45%).",
  "Сравни ключевые финметрики 2025 vs 2026 по портфелю (revenue, EBITDA, net profit). Что выросло, что упало? Учитывай макро (gold +15%, oil -5%).": "Portfelning 2025 va 2026-yillardagi asosiy moliyaviy ko‘rsatkichlarini (revenue, EBITDA, net profit) taqqosla. Nima o‘sdi, nima pasaydi? Makroni inobatga ol (gold +15%, oil -5%).",
  "Проверь кредитные ковенанты: Debt/EBITDA, ICR, current ratio по каждой компании. Где близко к breach? Используй get_financials + get_credit_portfolio.": "Har bir kompaniya bo‘yicha kredit kovenantlarini tekshir: Debt/EBITDA, ICR, current ratio. Qayerda breach ga yaqin? get_financials + get_credit_portfolio dan foydalan.",
