  "Сгенерируй прогноз ключевых показателей (выручка, EBITDA, чистая прибыль) на 2025–2027 по портфелю и крупнейшим компаниям: возьми историю из модуля финансов, при необходимости подтяни отраслевые темпы через web. Укажи метод и допущения. Выведи результат таблицами по годам (их можно скачать в Excel) и краткий вывод.": "Generate a 2025–2027 forecast of key indicators (revenue, EBITDA, net profit) for the portfolio and largest companies. Use history from the finance module and, where needed, fetch sector growth rates via the web. State the method and assumptions. Present the result in yearly tables that can be downloaded to Excel, followed by a brief conclusion.",
  "ИИ-аналитик финансов": "Financial AI analyst",
  "ИИ-аналитик": "AI analyst",
  "портфель · все компании": "portfolio · all companies",
  "Доступ к web-поиску. Таблицы из ответа можно скачать в Excel (кнопка под ответом). ИИ может ошибаться — проверяйте важные цифры.": "Web search is available. Tables in the response can be downloaded to Excel using the button below the response. AI can make mistakes, so verify important figures.",
  "Прогноз ИИ — выручка · EBITDA · прибыль на 2025–2027": "AI forecast — revenue · EBITDA · profit for 2025–2027",
