  "Расчётная оценка: 12% × выручка (НСБУ). Не учитывает нулевую ставку НДС на экспорт и зачёт входящего НДС — фактический НДС к уплате ниже. Для факта заполните «Налоги» в индикаторах компаний.": "Estimated value: 12% × revenue (NSBU). It does not account for the zero VAT rate on exports or input VAT credits, so actual VAT payable is lower. For actuals, complete Taxes in company indicators.",
