  "Удалить индикатор?": "Delete indicator?",
  "Удалить override для этого кредита?": "Delete the override for this loan?",
  "Раздел для управления сценариями кредитной нагрузки 22 SOEs. Все правки изолированы — не влияют на factual данные в credit-portfolio.": "Scenario management for the debt burden of 22 SOEs. All edits are isolated and do not affect factual data in credit-portfolio.",
  "Выбранный сценарий применяется ко всем расчётам ниже (KPI, формула риска, прогноз погашения).": "The selected scenario applies to all calculations below (KPIs, risk formula, repayment forecast).",
  "Выбор подмножества кредиторов для всех KPI и графиков ниже. По умолчанию — внутренние РУ (гос. + местные).": "Select the lender subset for all KPIs and charts below. Domestic lenders (state + local) are selected by default.",
  "Сводка по портфелю в области охвата. Пересчитывается при смене сценария.": "Portfolio summary within scope. Recalculated when the scenario changes.",
  "Текущая задолженность по выбранному scope. Учитывает % списания из сценария.": "Current debt for the selected scope. Accounts for the scenario’s write-off percentage.",
  "Возвращено = Программа − Outstanding. Включает плановые и досрочные выплаты.": "Repaid = Program − Outstanding. Includes scheduled and early payments.",
  "Σ(rate × debt) / Σ debt — взвешенная по размеру долга. Учитывает изменение ставки рефинанса из сценария.": "Σ(rate × debt) / Σ debt — weighted by debt size. Accounts for the scenario’s refinancing rate change.",
  "Доля кредитов с госгарантией. Влияет на recovery rate в формуле EL.": "Share of loans with a state guarantee. Affects the recovery rate in the EL formula.",
  "Платежи следующих 12 месяцев — основной долг + проценты по графику.": "Payments over the next 12 months — principal plus scheduled interest.",
  "Expected Loss = Σ debt × PD × (1 − RR). PD из формулы, RR из risk_rr_by_lender или is_guaranteed.": "Expected Loss = Σ debt × PD × (1 − RR). PD comes from the formula; RR comes from risk_rr_by_lender or is_guaranteed.",
  "Базовые гипотезы — применяются ко всему портфелю в этом сценарии. Сохраняются автоматически.": "Baseline assumptions apply to the entire portfolio in this scenario. Saved automatically.",
  "% основного долга, который государство простит. Применяется к кредитам с lender_type='state'.": "Percentage of principal forgiven by the state. Applies to loans with lender_type='state'.",
  "Изменение ставки рефинансирования в процентных пунктах (+/-). Применяется к гос. + местным.": "Refinancing rate change in percentage points (+/-). Applies to state + local loans.",
  "Базовая вероятность дефолта в этом сценарии (PD baseline). Может быть переопределена per-loan.": "Baseline probability of default in this scenario (PD baseline). Can be overridden per loan.",
  "% ускорения выплат от планового графика. Используется в прогнозе погашения.": "Payment acceleration percentage versus the planned schedule. Used in the repayment forecast.",
  "Python-выражение для расчёта Expected Loss. Возвращает финальное значение EL в USD. Безопасный AST-eval (без simpleeval).": "Python expression for calculating Expected Loss. Returns the final EL value in USD. Safe AST evaluation (without simpleeval).",
  "Custom-переменные, доступные в формуле через custom.<key>. Например: 'доля юаня', 'мораторий 2026'.": "Custom variables available in the formula through custom.<key>. For example: 'yuan share', 'moratorium 2026'.",
  "Топ-N кредитов по размеру долга. Inline-редактирование override: forgiveness% (% списания) и rate_override (новая ставка).": "Top-N loans by debt size. Inline editing of per-loan overrides: forgiveness% (write-off %) and rate_override (new rate).",
  "Read-only визуализация: топ-должники по Debt/EBITDA и квартальный график погашения.": "Read-only visualization: top borrowers by Debt/EBITDA and quarterly repayment schedule.",
  "Debt/EBITDA = долг / прибыль до налогов и амортизации. <2.5 здоровый, 2.5–3 повышенный, >3 критический.": "Debt/EBITDA = debt / earnings before interest, taxes, depreciation and amortization. <2.5 healthy, 2.5–3 elevated, >3 critical.",
  "Сумма плановых выплат (основной долг + проценты) по годам 2023–2030. Источник: loan_repayments.": "Scheduled payments (principal + interest) by year for 2023–2030. Source: loan_repayments.",
