  "{value0} млрд сум": "UZS {value0}bn",
  "{value0} млн сум": "UZS {value0}m",
  "Раздел связывает макроэкономику со сценариями. Состоит из 3 частей: эластичность (как метрики реагируют на макрофакторы), эффекты проектов (что даёт каждый проект в цифрах), декомпозиция (из чего складывается прогноз).": "This section links macroeconomics to scenarios. It has three parts: elasticity (how metrics respond to macro factors), project effects (what each project delivers numerically), and decomposition (what makes up the forecast).",
  "Эластичность β — на сколько % изменится метрика (например revenue) при изменении макрофактора (например USD-курс) на 1%. Если β=0.85 — это значит USD вырос на 10% → revenue вырастет на 8.5%.": "Elasticity β is the percentage change in a metric (for example, revenue) when a macro factor (for example, the USD exchange rate) changes by 1%. If β=0.85, a 10% increase in USD produces an 8.5% increase in revenue.",
  "Финансовые эффекты конкретных проектов трансформации. Команда проекта указывает: проект «X» в 2027 году даст +120 млрд сум к выручке с вероятностью 75%. Программа потом суммирует все такие эффекты в декомпозиции.": "Financial effects of specific transformation projects. A project team can state that project X will add UZS 120bn to revenue in 2027 with 75% probability. The system then aggregates all effects in the decomposition.",
  "Раскладывает прогноз на 3 части: База (факт прошлого года) + Эффект макроэкономики (через эластичности) + Эффект проектов (из их финансовых данных). Помогает понять, что именно даёт рост.": "Breaks the forecast into three parts: Baseline (previous-year actual) + Macroeconomic effect (through elasticities) + Project effect (from project financial data). This shows what drives growth.",
  "Иерархия применения коэффициента: специфичный сценарий + компания > сценарий > компания > глобально. Программа берёт самый специфичный из имеющихся.": "Coefficient precedence: specific scenario + company > scenario > company > global. The system uses the most specific available value.",
  "Эластичность и эффекты проектов": "Elasticity and project effects",
  "Связывает макроэкономику со сценариями:": "Links macroeconomics to scenarios:",
  "эластичность": "elasticity",
  "= чувствительность к макрофакторам ·": "= sensitivity to macro factors ·",
  "эффекты проектов": "project effects",
  "= эффект конкретных проектов в цифрах ·": "= numeric effect of specific projects ·",
  "декомпозиция": "decomposition",
  "= из чего складывается прогноз.": "= what makes up the forecast.",
  "⟳ Обновить": "⟳ Refresh",
  "Матрица эластичности": "Elasticity matrix",
  "Эффекты проектов": "Project effects",
  "Декомпозиция прогноза": "Forecast decomposition",
  "Что это:": "What this is:",
  "Как читать β:": "How to read β:",
  "β &gt; 0 — растёт вместе с фактором": "β &gt; 0 — rises with the factor",
  "β &lt; 0 — падает при росте фактора": "β &lt; 0 — falls as the factor rises",
  "β = 0 — нечувствительно": "β = 0 — not sensitive",
  "Сила:": "Strength:",
  "|β|&lt;0.3 — слабая · 0.3–0.7 — средняя · &gt;0.7 — сильная.": "|β|&lt;0.3 — weak · 0.3–0.7 — medium · &gt;0.7 — strong.",
  "Все (глобальные дефолты)": "All (global defaults)",
  "Целевая метрика": "Target metric",
  "Все метрики": "All metrics",
  "+ Добавить коэффициент": "+ Add coefficient",
  "Скоуп": "Scope",
  "Макрофактор": "Macro factor",
  "Влияет на": "Affects",
  "Нет коэффициентов в этом срезе. Запустите миграции и сидинг через": "No coefficients in this view. Run migrations and seeding through",
  "чтобы создать глобальные дефолты.": "to create global defaults.",
  "Логика:": "Logic:",
  "у каждого проекта может быть много эффектов — один на каждую пару (год × метрика). Например: «Modernize plant X»: +50 млрд сум к revenue в 2026, +120 в 2027.": "each project can have multiple effects, one for every (year × metric) pair. For example, Modernize plant X: +UZS 50bn to revenue in 2026 and +UZS 120bn in 2027.",
  "Заполнение:": "Data entry:",
  "данные вносят команды проектов. Пока поля пустые — прогноз считает что эффект = 0. Появятся данные → автоматически отразятся в декомпозиции.": "project teams enter the data. While fields are empty, the forecast treats the effect as 0. New data appears in the decomposition automatically.",
  "+ Добавить эффект": "+ Add effect",
  "Δ млн сум": "Δ UZS m",
  "Вероятн.": "Probability",
  "Уверен.": "Confidence",
  "В этом срезе (": "In this view (",
  ") ещё никто не указал эффекты проектов. Заполняется через UI этого раздела или REST API.": ") no project effects have been entered yet. Add them through this section’s UI or REST API.",
  "Формула:": "Formula:",
  "Прогноз = База × Π(1 + Δfactor × β) + Σ эффекты проектов": "Forecast = Baseline × Π(1 + Δfactor × β) + Σ project effects",
