  "Выбери сценарий, метрику и год и нажми «Рассчитать». Если база = 0 — значит для этой компании нет финансовых данных за предыдущий год.": "Select a scenario, metric, and year, then click Calculate. If baseline = 0, the company has no financial data for the previous year.",
