  "категория {id}": "category {id}",
  "Лидер рейтинга. Хорошие практики по <b>{category}</b> ({percent}% к рынку) — рассмотреть как образец для других компаний.": "Rating leader. Consider strong practices in <b>{category}</b> ({percent}% vs market) as a model for other companies.",
  " и ": " and ",
  "Сосредоточиться на <b>{categories}</b> — потенциал экономии {amount} сум.": "Focus on <b>{categories}</b> — savings potential is UZS {amount}.",
  "Точечная оптимизация по <b>{category}</b> ({percent}% к рынку).": "Targeted optimization in <b>{category}</b> ({percent}% vs market).",
  "Закупки в пределах нормы. Продолжать мониторинг динамики цен.": "Purchases are within the normal range. Continue monitoring price trends.",
  "Среднее отклонение <b style=\"color:#C53030\">+{deviation}%</b> требует внимания. Особое отклонение в категории <b>{category}</b> ({worstDeviation}%). Рекомендуется аудит закупочных процедур и пересмотр поставщиков по топ-3 проблемным категориям. Потенциал экономии при переходе на средние цены — <b>{amount} сум/год</b>.": "Average deviation of <b style=\"color:#C53030\">+{deviation}%</b> requires attention. Deviation is especially high in <b>{category}</b> ({worstDeviation}%). Audit procurement procedures and review suppliers in the top three problem categories. Potential savings from moving to average prices: <b>UZS {amount}/year</b>.",
  "Среднее отклонение <b style=\"color:#B07415\">+{deviation}%</b> — в пределах нормы. По {redCount} категориям из {categoryCount} закупка выше рынка. Рекомендуется мониторинг этих категорий и сравнение поставщиков с лидерами рейтинга.": "Average deviation of <b style=\"color:#B07415\">+{deviation}%</b> is within the normal range. Purchases are above market in {redCount} of {categoryCount} categories. Monitor these categories and compare suppliers with rating leaders.",
  "Среднее отклонение <b style=\"color:#0F6E56\">{deviation}%</b> — закупки эффективнее рынка. Хорошие закупочные практики — стоит задокументировать методику и поделиться с другими компаниями. Экономия за период составила <b>{amount} сум</b>.": "Average deviation of <b style=\"color:#0F6E56\">{deviation}%</b> means purchases outperform the market. Document the strong procurement approach and share it with other companies. Savings for the period were <b>UZS {amount}</b>.",
