  "ШАБЛОН ИМПОРТА · Закупки и Форензик аудит · {year} год": "IMPORT TEMPLATE · Procurement and Forensic audit · {year}",
  "КАК ЗАПОЛНЯТЬ:": "HOW TO COMPLETE:",
  "1. Лист «Компании» — справочник, не редактируйте.": "1. The Companies sheet is a reference; do not edit it.",
  "2. Лист «Данные» — заполните по каждой компании план/факт по году + квартально.": "2. In the Data sheet, complete annual and quarterly plan/actual values for each company.",
  "ПОЛЯ:": "FIELDS:",
  "• Код компании — обязателен, ровно как в листе «Компании».": "• Company code is required and must exactly match the Companies sheet.",
  "• Год — 4-значное число.": "• Year is a four-digit number.",
  "• Все суммы — в млрд сум, только числа (без пробелов / валют).": "• All amounts are in UZS billions, numbers only (no spaces or currency symbols).",
  "• Статус плана: «Утверждён» / «Не утверждён» / пусто.": "• Plan status: Approved / Not approved / blank.",
  "• Статус форензика: «Завершён» / «В процессе» / «Тендер в YYYY» / «Не начат» / пусто.": "• Forensic status: Completed / In progress / Tender in YYYY / Not started / blank.",
  "• Аудитор: KPMG / PwC / Deloitte / E&Y (или пусто).": "• Auditor: KPMG / PwC / Deloitte / E&Y (or blank).",
