  "КАК ИМПОРТИРОВАТЬ": "HOW TO IMPORT",
  "1. Один лист = одна компания. Имя листа — КОД из таблицы «Коды компаний» (NGMK, AGMK…). Регистр не важен.": "1. One sheet = one company. The sheet name must be the CODE from the Company codes table (NGMK, AGMK…). Case does not matter.",
  "2. Первая строка листа — заголовки колонок РОВНО как на листе «ОБРАЗЕЦ» (имена нельзя менять/переводить).": "2. The first row contains column headers EXACTLY as on the SAMPLE sheet (names must not be changed or translated).",
  "3. Каждая следующая строка — одна позиция (товар/услуга/работа) внутри лота.": "3. Each subsequent row is one item (product/service/work) within a lot.",
  "4. Несколько товаров одного лота — несколько строк с ОДНИМ lotId (сумма контракта учитывается один раз).": "4. Multiple products in one lot use multiple rows with the SAME lotId (the contract amount is counted once).",
  "5. Листы «СПРАВКА» и «ОБРАЗЕЦ» при импорте игнорируются (их имена — не коды компаний).": "5. REFERENCE and SAMPLE sheets are ignored during import (their names are not company codes).",
  "6. Загрузка: модуль «Анализ закупок» → меню ⋯ → Импорт Excel.": "6. Upload: Procurement analysis module → ⋯ menu → Import Excel.",
  "КОЛОНКИ (имя — обязательность — описание)": "COLUMNS (name — requirement — description)",
  "обязательно": "required",
  "ID лота/контракта. Строки с одним lotId = один лот.": "Lot/contract ID. Rows with the same lotId represent one lot.",
  "желательно": "recommended",
  "Дата контракта, формат YYYY-MM-DD.": "Contract date in YYYY-MM-DD format.",
  "опц.": "optional",
  "Дата начала процедуры, YYYY-MM-DD.": "Procedure start date, YYYY-MM-DD.",
  "Способ закупки — см. «Способы закупки» ниже.": "Procurement method — see Procurement methods below.",
  "Электронная площадка (например xarid.uz).": "Electronic marketplace (for example, xarid.uz).",
  "Наименование поставщика.": "Supplier name.",
  "ИНН поставщика (для сквозных поставщиков/концентрации).": "Supplier tax ID (for cross-company suppliers/concentration).",
  "Регион.": "Region.",
  "Номер категории 1–15 (см. «Категории»). Пусто → «Без категории».": "Category number 1–15 (see Categories). Blank → Uncategorized.",
  "ВАЖНО": "IMPORTANT",
  "Код товара (KTRU). По нему считается рыночная медиана и сравнение цен. Без кода — позиция не попадёт в ценовой бенчмарк.": "Product code (KTRU). Market median and price comparison are calculated from it. An item without a code is excluded from the price benchmark.",
  "Наименование товара/услуги.": "Product/service name.",
  "PRODUCT (товар) / SERVICE (услуга) / WORK (работа). Пусто → определяется по ед.изм.": "PRODUCT / SERVICE / WORK. Blank → inferred from the unit of measure.",
  "Единица измерения (шт, кг, т, л … ; для услуг часто «shartli birlik»).": "Unit of measure (pcs, kg, t, l …; services often use a notional unit).",
  "Количество (число > 0).": "Quantity (number > 0).",
  "обязательно*": "required*",
  "Цена за единицу (число > 0). *Если пусто — будет вычислено как contractAmount / amount.": "Unit price (number > 0). *If blank, calculated as contractAmount / amount.",
  "Начальная сумма процедуры (UZS).": "Initial procedure amount (UZS).",
  "Сумма контракта (UZS). Источник «спенда» лота; при пустой Unit price — основа для расчёта цены.": "Contract amount (UZS). Source of lot spend; if Unit price is blank, the basis for calculating price.",
  "Сэкономлено на торгах (UZS).": "Savings achieved through bidding (UZS).",
  "Процент экономии.": "Savings percentage.",
  "СПОСОБЫ ЗАКУПКИ (purchaseType)": "PROCUREMENT METHODS (purchaseType)",
  "электронный магазин/каталог (НЕконкурентный — торга нет)": "electronic shop/catalog (NON-competitive — no bidding)",
  "аукцион (конкурентный)": "auction (competitive)",
