  "POST с JSON-телом, header": "POST with a JSON body and header",
  "(HMAC от secret, выданного при создании subscription). Ретраи: 5 попыток с back-off 1m → 5m → 15m → 1h → 6h.": "(HMAC of the secret issued when the subscription was created). Retries: five attempts with back-off 1m → 5m → 15m → 1h → 6h.",
  "Real-time WebSocket (альтернатива)": "Real-time WebSocket (alternative)",
