  "Дай аналитическую сводку по портфелю из 22 SOE: ключевые цифры, лидеры и отстающие, общая динамика. Используй get_kpi_summary.": "Give an analytical summary of the 22-SOE portfolio: key figures, leaders and laggards, and overall trend. Use get_kpi_summary.",
  "Найди топ-3 риска в портфеле: где провал KPI, где просрочки концентрируются, где credit-risk. Конкретные компании + рекомендации.": "Find the top three portfolio risks: KPI failures, concentrations of overdue work, and credit risk. Name specific companies and recommendations.",
  "Проанализируй IPO-готовность портфеля: какие компании ближе всего к IPO, какие блокеры (governance/ESG/KPI) у каждой из IPO-roadmap.": "Analyze portfolio IPO readiness: which companies are closest to IPO and what blockers (governance/ESG/KPI) each IPO-roadmap company has.",
  "Используй compare_years, чтобы сравнить выполнение задач 2025 vs 2026 и compare_companies по EBITDA. Сделай вывод.": "Use compare_years to compare task completion in 2025 vs 2026 and compare_companies for EBITDA. Draw a conclusion.",
  "Что важного на сегодня: просроченные критичные задачи, недавние события модерации, активные алерты. Используй list_overdue_tasks + get_moderation_queue + list_notifications.": "What matters today: critically overdue tasks, recent moderation events, and active alerts. Use list_overdue_tasks + get_moderation_queue + list_notifications.",
  "FY {year} · {standard} · {currency} · {unit} · {view} · метрика {metric}": "FY {year} · {standard} · {currency} · {unit} · {view} · metric {metric}",
  " · сектор {sector}": " · sector {sector}",
  "Дай сводку финансовых результатов портфеля за выбранный год: revenue, EBITDA, net profit, топ-5 компаний. Используй get_financials.": "Summarize portfolio financial results for the selected year: revenue, EBITDA, net profit, and top five companies. Use get_financials.",
  "Проанализируй EBITDA-margin по портфелю: лидеры и отстающие, сравнение с отраслевыми бенчмарками (mining 25-45%, energy 15-25%, transport 10-20%, telecom 30-45%).": "Analyze portfolio EBITDA margin: leaders and laggards compared with sector benchmarks (mining 25-45%, energy 15-25%, transport 10-20%, telecom 30-45%).",
  "Сравни ключевые финметрики 2025 vs 2026 по портфелю (revenue, EBITDA, net profit). Что выросло, что упало? Учитывай макро (gold +15%, oil -5%).": "Compare key portfolio financial metrics for 2025 vs 2026 (revenue, EBITDA, net profit). What rose and what fell? Account for macro factors (gold +15%, oil -5%).",
  "Проверь кредитные ковенанты: Debt/EBITDA, ICR, current ratio по каждой компании. Где близко к breach? Используй get_financials + get_credit_portfolio.": "Check credit covenants for each company: Debt/EBITDA, ICR, and current ratio. Which are close to breach? Use get_financials + get_credit_portfolio.",
