  "Как это работает:": "How it works:",
  "Курсы USD/EUR/UZS — переключатель валют во всех KPI и модалках исполнительного дашборда. Бюджет Республики — расчёт «процент бюджета Республики» в налоговом блоке. Макроэкономические показатели — справочные значения для аналитических отчётов и фильтров. Изменения сохраняются моментально и подхватываются всеми открытыми блоками без перезагрузки страницы.": "USD/EUR/UZS rates drive the currency switcher in all KPIs and modals of the executive dashboard. The state budget drives the percentage of state budget calculation in the tax block. Macroeconomic indicators are reference values for analytical reports and filters. Changes save instantly and propagate to all open blocks without a page reload.",
  "Для добавления других валют или индикаторов (CNY, RUB, ставка рефинансирования и т.д.) — нужна миграция БД (новая колонка в": "Adding other currencies or indicators (CNY, RUB, refinancing rate, etc.) requires a database migration (a new column in",
